/* ===================== BÀI 8 · Little-endian, word và giới hạn ===================== */
/* Bài 8 · Little-endian, word và giới hạn (AMTS-EMB-002-M02-L04, X86-008) — sinh bởi tools/author/mpu8086/l08.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P8=[{"label": "Ví dụ: word 1234h nằm trong bộ nhớ ra sao", "code": "; Ví dụ 1: word 1234h nằm trong bộ nhớ ra sao\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DW      1234H                   ; độ lệch 0 và 1\nthap    DB      ?                       ; byte ở địa chỉ thấp của so\ncao     DB      ?                       ; byte ở địa chỉ cao của so\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, BYTE PTR so         ; byte ở độ lệch 0\n        MOV     thap, AL                ; 34h: byte thấp đứng trước\n        MOV     AL, BYTE PTR so+1       ; byte ở độ lệch 1\n        MOV     cao, AL                 ; 12h\n        MOV     AX, so                  ; đọc cả word: AX = 1234h\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "so DW 1234h nằm trong hai ô: độ lệch 0 chứa 34h, độ lệch 1 chứa 12h (xem phần Bộ nhớ: 34 12). Đọc từng byte bằng BYTE PTR so và BYTE PTR so+1, rồi đọc cả word: AX = 1234h. Byte ở địa chỉ lẻ (so+1) không tốn thêm chu kỳ. Đoán trước: sau MOV AL, BYTE PTR so, AL bằng bao nhiêu? Đáp án 34h."}, {"label": "Ví dụ: số 32 bit là hai word, word thấp trước", "code": "; Ví dụ 2: số 32 bit (DD) là hai word, word thấp trước\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nx       DD      12345678H               ; 4 byte: 78 56 34 12\nlo      DW      ?                       ; word thấp của x\nhi      DW      ?                       ; word cao của x\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, WORD PTR x          ; độ lệch 0: AX = 5678h\n        MOV     DX, WORD PTR x+2        ; độ lệch 2: DX = 1234h\n        MOV     lo, AX\n        MOV     hi, DX                  ; DX:AX = 12345678h\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "x DD 12345678h là bốn byte 78 56 34 12. WORD PTR x là word thấp 5678h, WORD PTR x+2 là word cao 1234h: DX:AX = 12345678h. MOV DX, mem không có dạng ngắn như AX nên 8 + 6 = 14 chu kỳ. Đoán trước: sau MOV AX, WORD PTR x, AX bằng bao nhiêu? Đáp án 5678h."}, {"label": "Lỗi: đọc đảo byte dữ liệu nhận được", "code": "; Lỗi: đọc đảo byte dữ liệu nhận theo thứ tự byte cao trước\n; Giả định: thiết bị gửi giá trị 1234h thành hai byte 12h, 34h\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nnhan    DB      12H, 34H                ; hai byte theo thứ tự nhận được\ngiatri  DW      ?                       ; cần bằng 1234h\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, WORD PTR nhan       ; AL = 12h, AH = 34h: AX = 3412h\n        MOV     giatri, AX              ; sai: thiếu XCHG AH, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý (lỗi logic, chương trình vẫn chạy hết): hai byte 12h, 34h theo thứ tự đến được đọc thành word 3412h, vì byte đầu thành byte thấp. Sửa: thêm XCHG AH, AL trước MOV giatri, AX (giatri = 1234h, bộ nhớ 34 12), hoặc lưu byte cao vào địa chỉ cao ngay từ đầu. Đoán trước: sau MOV AX, WORD PTR nhan, AX bằng bao nhiêu? Đáp án 3412h."}, {"label": "Lỗi: đọc biến byte vào thanh ghi 16 bit", "code": "; Lỗi: đọc biến byte vào thanh ghi 16 bit\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\np       DB      41H, 42H\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, p                   ; lỗi: p là DB, AX là 16 bit\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch cố ý: p khai báo DB (byte) mà AX 16 bit. Trình dịch báo ở dòng 10. Sửa: MOV AL, p nếu cần một byte, MOV AX, WORD PTR p nếu thật sự muốn hai byte p, p+1 (AX = 4241h)."}, {"label": "Ví dụ: word ở địa chỉ lẻ tốn thêm 4 chu kỳ", "code": "; Ví dụ 5: word ở địa chỉ lẻ tốn thêm 4 chu kỳ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DW      1111H                   ; độ lệch 0 (chẵn)\nc       DB      0                       ; độ lệch 2\nb       DW      2222H                   ; độ lệch 3 (lẻ)\n        EVEN                            ; đệm 1 byte cho biến sau\nd       DW      3333H                   ; độ lệch 6 (chẵn)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, a                   ; word chẵn: 10 chu kỳ\n        MOV     AX, b                   ; word lẻ: 10 + 4\n        MOV     AX, d                   ; word chẵn: 10\n        MOV     AL, BYTE PTR b          ; byte lẻ: vẫn 10\n        MOV     b, AX                   ; ghi word lẻ: 10 + 4\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Cùng lệnh MOV AX, biến: 10 chu kỳ với a (độ lệch 0) và d (độ lệch 6, nhờ EVEN), 14 chu kỳ với b (độ lệch 3). Đọc một byte ở địa chỉ lẻ vẫn 10; ghi word vào b lại 14. Xem cột chu kỳ ở phần Mã máy và chu kỳ. Đoán trước: MOV AX, b tốn bao nhiêu chu kỳ? Đáp án 14."}, {"label": "Bẫy: word ở FFFFh lấy byte cao ở đầu đoạn", "code": "; Ví dụ 6: độ lệch quay vòng trong đoạn 64 KB\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndau     DB      'Q'                     ; độ lệch 0000h của DS\nkq      DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BX, 0FFFFH              ; độ lệch cuối của đoạn\n        MOV     AX, [BX]                ; AL = DS:FFFF, AH = DS:0000\n        MOV     kq, AH                  ; 'Q': byte cao lấy ở đầu đoạn\n        INC     BX                      ; FFFFh + 1 = 0000h\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy cố ý: dễ nghĩ byte cao của word ở DS:FFFF nằm ở ô kế tiếp ngoài đoạn (DS × 16 + 10000h), nhưng 8086 quay vòng độ lệch. BX = FFFFh: word ở DS:FFFF lấy byte thấp ở DS:FFFF (trình mô phỏng: 00h; máy thật: byte bất kỳ) và byte cao ở DS:0000 = 'Q'. INC BX đưa BX về 0000h. 8 + 5 + 4 = 17 chu kỳ vì word lẻ. Đoán trước: sau MOV AX, [BX], AH bằng bao nhiêu? Đáp án 51h ('Q')."}, {"label": "Ví dụ: FFFF:0500 quay vòng về đầu bộ nhớ", "code": "; Ví dụ 7: FFFF:0500 quay vòng về 004F0h (20 đường địa chỉ)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     AX, AX\n        MOV     ES, AX                  ; ES = 0000h\n        MOV     BYTE PTR ES:[04F0H], 'M' ; ghi vào 004F0h\n        MOV     AX, 0FFFFH\n        MOV     ES, AX                  ; ES = FFFFh\n        MOV     AL, ES:[0500H]          ; FFFF0h + 0500h = 1004F0h\n        MOV     kq, AL                  ; bit 20 bị bỏ: đọc lại 'M'\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Ghi 'M' vào 0000:04F0 (ô 004F0h) rồi đọc FFFF:0500: FFFF0h + 500h = 1004F0h, 8086 chỉ có 20 đường địa chỉ nên bit 20 bị bỏ, đọc lại đúng ô 004F0h. Xem hình địa chỉ vật lý ở phần Thanh ghi. Trên máy có A20 mở, lệnh đọc này rơi vào 1004F0h (CẦN XÁC MINH trên Windows). Đoán trước: kq bằng bao nhiêu? Đáp án 4Dh ('M')."}];
const sim8=makeX86Sim(document.getElementById("x86-l8"),{id:"s8",presets:P8,file:"BAI8.ASM"});
makeX86Ex(document.getElementById("ex-l8"),sim8,[{"t": "Sửa số bị đảo byte", "d": "Một thiết bị gửi số 32 bit thành 4 byte theo thứ tự byte cao nhất trước (giả định của đề). Đọc 4 phím bằng INT 21h hàm 08h: phím 1 là byte cao nhất (bit 24–31), phím 4 là byte thấp nhất (bit 0–7). Ghi số vào biến so (DD) đúng cách lưu của 8086 để MOV AX, WORD PTR so và MOV DX, WORD PTR so+2 cho DX:AX bằng số đó. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: ghi số 32 bit nhận theo thứ tự byte cao trước\n; Bản này ghi byte theo thứ tự phím nên số bị đảo. Hãy sửa.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DD      ?                       ; 4 byte: so, so+1, so+2, so+3\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; phím 1: byte cao nhất\n        MOV     BYTE PTR so, AL\n        MOV     AH, 08H\n        INT     21H                     ; phím 2\n        MOV     BYTE PTR so+1, AL\n        MOV     AH, 08H\n        INT     21H                     ; phím 3\n        MOV     BYTE PTR so+2, AL\n        MOV     AH, 08H\n        INT     21H                     ; phím 4: byte thấp nhất\n        MOV     BYTE PTR so+3, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "ABCD", "mem": [{"at": "so", "bytes": [68, 67, 66, 65]}]}, {"in": "1234", "mem": [{"at": "so", "bytes": [52, 51, 50, 49]}]}, {"in": "ABBA", "mem": [{"at": "so", "bytes": [65, 66, 66, 65]}]}, {"in": "~!0z", "mem": [{"at": "so", "bytes": [122, 48, 33, 126]}]}, {"in": "    ", "mem": [{"at": "so", "bytes": [32, 32, 32, 32]}]}, {"in": "Az09", "mem": [{"at": "so", "bytes": [57, 48, 122, 65]}]}]}, {"t": "Cộng hai số 32 bit", "d": "Biến a (DD) nhận 4 phím theo thứ tự trong bộ nhớ: phím 1 vào a, phím 2 vào a+1, phím 3 vào a+2, phím 4 vào a+3 (code mẫu đã làm). Tính c = a + b với b DD 1234ABCDh, bỏ số nhớ ra khỏi bit 31, dùng phép cộng 16 bit. Code mẫu cộng sai thứ tự hai word. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: c = a + b, ba số 32 bit (DD) little-endian\n; Bản này coi word ở độ lệch thấp là word cao nên cộng\n; sai thứ tự và số nhớ đi nhầm hướng. Hãy sửa phần cộng.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DD      ?                       ; 4 phím, theo thứ tự trong bộ nhớ\nb       DD      1234ABCDH\nc       DD      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        MOV     BYTE PTR a, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     BYTE PTR a+1, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     BYTE PTR a+2, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     BYTE PTR a+3, AL\n; cộng (sai: word cao trước, ADC ở word thấp)\n        MOV     AX, WORD PTR a+2\n        ADD     AX, WORD PTR b+2\n        MOV     WORD PTR c+2, AX\n        MOV     AX, WORD PTR a\n        ADC     AX, WORD PTR b\n        MOV     WORD PTR c, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "    ", "mem": [{"at": "c", "bytes": [237, 203, 84, 50]}]}, {"in": "zzzz", "mem": [{"at": "c", "bytes": [71, 38, 175, 140]}]}, {"in": "AT  ", "mem": [{"at": "c", "bytes": [14, 0, 85, 50]}]}, {"in": "AS  ", "mem": [{"at": "c", "bytes": [14, 255, 84, 50]}]}, {"in": "~~~~", "mem": [{"at": "c", "bytes": [75, 42, 179, 144]}]}, {"in": "0Z12", "mem": [{"at": "c", "bytes": [253, 5, 102, 68]}]}]}, {"t": "Tổng bảng word nhanh", "d": "Đọc 8 phím vào bảng bang (4 word, phím 1 vào bang, phím 2 vào bang+1, …), rồi tính tong (DW) = tổng 4 word, bỏ phần tràn ra khỏi 16 bit. Code mẫu đã đúng nhưng chậm: dùng hai vòng lặp và đặt biến n trước bảng nên mọi word nằm ở địa chỉ lẻ. Viết lại (được sửa cả .DATA, giữ tên bang và tong) để đạt cả giới hạn chu kỳ và giới hạn số byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: tổng 4 word của bảng, nhanh\n; Bản này đúng nhưng chậm: hai vòng lặp, và mọi word\n; nằm ở địa chỉ lẻ. Hãy viết lại (được sửa cả .DATA).\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nn       DB      4                       ; số word của bảng\nbang    DW      4 DUP(?)                ; 8 phím, theo thứ tự trong bộ nhớ\ntong    DW      ?                       ; tổng 4 word, bỏ phần tràn\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET bang\n        MOV     CX, 8\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        MOV     [SI], AL                ; phím vào bảng\n        INC     SI\n        LOOP    doc\n        MOV     SI, OFFSET bang\n        MOV     CL, n                   ; CX = 4 (CH = 0 sau LOOP)\n        XOR     AX, AX\ncong:\n        ADD     AX, [SI]                ; word ở địa chỉ lẻ: thêm 4 chu kỳ\n        ADD     SI, 2\n        LOOP    cong\n        MOV     tong, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "ABCDEFGH", "mem": [{"at": "bang", "bytes": [65, 66, 67, 68, 69, 70, 71, 72]}, {"at": "tong", "word": 5392}]}, {"in": "        ", "mem": [{"at": "bang", "bytes": [32, 32, 32, 32, 32, 32, 32, 32]}, {"at": "tong", "word": 32896}]}, {"in": "~~~~~~~~", "mem": [{"at": "bang", "bytes": [126, 126, 126, 126, 126, 126, 126, 126]}, {"at": "tong", "word": 63992}]}, {"in": "01234567", "mem": [{"at": "bang", "bytes": [48, 49, 50, 51, 52, 53, 54, 55]}, {"at": "tong", "word": 53452}]}, {"in": "!~!~!~!~", "mem": [{"at": "bang", "bytes": [33, 126, 33, 126, 33, 126, 33, 126]}, {"at": "tong", "word": 63620}]}, {"in": "zzzzzzzz", "mem": [{"at": "bang", "bytes": [122, 122, 122, 122, 122, 122, 122, 122]}, {"at": "tong", "word": 59880}]}], "perf": {"cycles": 655, "bytes": 90}}]);

makeQuiz("quiz8","score8",[{"q": "Sau <code>v DW 0ABCDh<\/code>, hai byte ở v và v+1 lần lượt là gì?", "o": ["ABh rồi CDh", "0Ah rồi BCh", "DCh rồi BAh", "CDh rồi ABh"], "a": 3, "e": "Little-endian: byte thấp (CDh) ở địa chỉ thấp v, byte cao (ABh) ở v+1. DCh, BAh là đảo chữ số hệ 16, không phải đảo byte."}, {"q": "Bộ nhớ từ độ lệch của <code>x<\/code> chứa <code>78 56 34 12<\/code>. Sau <code>MOV AX, WORD PTR x+1<\/code>, AX bằng bao nhiêu?", "o": ["3456h", "5634h", "5678h", "1234h"], "a": 0, "e": "WORD PTR x+1 lấy x+1 = 56h làm byte thấp và x+2 = 34h làm byte cao: AX = 3456h. Word này lại ở địa chỉ lẻ nếu x chẵn, nên tốn thêm 4 chu kỳ."}, {"q": "Với <code>c DB 0<\/code> ở độ lệch 0 và <code>w DW 5<\/code> ngay sau (độ lệch 1), <code>MOV AX, w<\/code> tốn bao nhiêu chu kỳ trên 8086?", "o": ["10: lệnh MOV AX, biến luôn 10", "12: cộng 2 cho tiền tố đoạn", "14: 10 cộng 4 vì word ở địa chỉ lẻ", "20: đọc hai byte là hai lệnh"], "a": 2, "e": "MOV AX, biến là 10 chu kỳ; w ở địa chỉ lẻ nên 8086 cần hai chu kỳ bus: +4 = 14. Không có tiền tố đoạn trong lệnh này."}, {"q": "BX = FFFFh, DS = 2000h. <code>MOV AX, [BX]<\/code> trên 8086 lấy byte cao (AH) từ địa chỉ vật lý nào?", "o": ["30000h: độ lệch tràn sang đoạn kế tiếp", "2FFFFh: đọc lại cùng ô với byte thấp", "20000h: độ lệch quay về 0000h trong cùng đoạn", "Không đọc được: 8086 báo lỗi"], "a": 2, "e": "Độ lệch FFFFh + 1 = 0000h (16 bit), nên byte cao ở 2000:0000 = 20000h. 8086 không báo lỗi; các CPU sau xử lý khác (bảng mục 8.4, CẦN XÁC MINH)."}, {"q": "Trên 8086, đoạn:độ lệch FFFF:0020 chỉ địa chỉ vật lý nào?", "o": ["100010h", "00010h", "FFFF20h", "0FFF0h"], "a": 1, "e": "FFFF0h + 0020h = 100010h, nhưng 8086 chỉ có 20 đường địa chỉ nên bit 20 bị bỏ: 00010h. 100010h là kết quả trên máy có đường A20 mở."}]);

